const rentalCategories=()=>({all:t('Kõik','All'),table:t('Lauakaunistused','Table decorations'),large:t('Suured dekoratsioonid','Large decorations'),clothes:t('Riided','Clothing')});
const sampleProducts=[{"id":"veil-1","category":"clothes","name":{"et":"Loor I","en":"Veil I"},"description":{"et":"Loorimudel 1. Täpsed mõõdud ja foto lisanduvad.","en":"Veil style 1. Exact dimensions and photograph will be added."},"price":70,"stock":1},{"id":"veil-2","category":"clothes","name":{"et":"Loor II","en":"Veil II"},"description":{"et":"Loorimudel 2. Täpsed mõõdud ja foto lisanduvad.","en":"Veil style 2. Exact dimensions and photograph will be added."},"price":70,"stock":1},{"id":"candle-1","category":"table","name":{"et":"Küünlatops · suurus 1","en":"Candle holder · size 1"},"description":{"et":"Küünlatops, suurus 1. Täpsed mõõdud lisanduvad.","en":"Candle holder, size 1. Exact dimensions will be added."},"price":3,"stock":12},{"id":"candle-2","category":"table","name":{"et":"Küünlatops · suurus 2","en":"Candle holder · size 2"},"description":{"et":"Küünlatops, suurus 2. Täpsed mõõdud lisanduvad.","en":"Candle holder, size 2. Exact dimensions will be added."},"price":3,"stock":12},{"id":"candle-3","category":"table","name":{"et":"Küünlatops · suurus 3","en":"Candle holder · size 3"},"description":{"et":"Küünlatops, suurus 3. Täpsed mõõdud lisanduvad.","en":"Candle holder, size 3. Exact dimensions will be added."},"price":3,"stock":12},{"id":"candle-4","category":"table","name":{"et":"Küünlatops · suurus 4","en":"Candle holder · size 4"},"description":{"et":"Küünlatops, suurus 4. Täpsed mõõdud lisanduvad.","en":"Candle holder, size 4. Exact dimensions will be added."},"price":3,"stock":12},{"id":"candle-5","category":"table","name":{"et":"Küünlatops · suurus 5","en":"Candle holder · size 5"},"description":{"et":"Küünlatops, suurus 5. Täpsed mõõdud lisanduvad.","en":"Candle holder, size 5. Exact dimensions will be added."},"price":3,"stock":12},{"id":"wedding-arch","category":"large","name":{"et":"Pulmakaar","en":"Wedding arch"},"description":{"et":"Pulmakaar tseremoonia jaoks. Mõõdud ja transpordi üksikasjad täpsustatakse enne üleandmist.","en":"An arch for your ceremony. Dimensions and transport details are confirmed before handover."},"price":30,"stock":1},{"id":"guestbook-phone","category":"table","name":{"et":"Külalisteraamatu telefon","en":"Audio guestbook telephone"},"description":{"et":"Telefon külaliste häälsõnumite salvestamiseks. Mälukaart on komplektis.","en":"A telephone for recording voice messages from your guests. Memory card included."},"price":30,"stock":1}];
let rentalProducts=sampleProducts,rentalMode='unavailable',rentalFilter='all',selectedProduct=null,calendarMonth=new Date(),calendarData=null,calendarLoading=false,calendarError=false,calendarRequest=0,bookingBusy=false,bookingComplete=false,bookingAttempt=null;
const escapeText=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const locale=()=>lang==='et'?'et-EE':'en-GB';
function tallinnDate(d=new Date()){const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Tallinn',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d);return ['year','month','day'].map(k=>p.find(x=>x.type===k).value).join('-')}
function tallinnStart(date,time){
 if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!/^\d{2}:\d{2}$/.test(time))throw Error('Invalid date');
 const target=Date.parse(date+'T'+time+':00Z');let stamp=target;
 for(let i=0;i<3;i++){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Tallinn',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date(stamp)),p=Object.fromEntries(parts.map(x=>[x.type,x.value]));const actual=Date.parse(`${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}:${p.second}Z`);stamp+=target-actual}
 return new Date(stamp).toISOString();
}
const dateTime=iso=>new Intl.DateTimeFormat(locale(),{timeZone:'Europe/Tallinn',dateStyle:'medium',timeStyle:'short'}).format(new Date(iso));
function rentals(){return `<section class="page-heading"><span class="eyebrow">${t('RENDIKOLLEKTSIOON','RENTAL COLLECTION')}</span><h1>${t('Detailid, mis<br><em>loovad meeleolu.</em>','Details that<br><em>set the mood.</em>')}</h1><p>${t('Valige toode, vaadake kalendrit ja planeerige rendiperiood. Tavapärane kasutusaeg on 36 tundi.','Choose an item, check the calendar and plan your rental. The standard use period is 36 hours.')}</p></section><section class="section rental-section"><div class="rental-filters" role="group" aria-label="${t('Tootekategooriad','Product categories')}">${Object.entries(rentalCategories()).map(([id,name])=>`<button type="button" data-category="${id}" aria-pressed="${id==='all'}">${name}</button>`).join('')}</div><p id="catalog-status" class="small" role="status"></p><div class="product-grid" id="product-grid"></div><div class="notice">${t('Baashind sisaldab 36 tunni kasutusaega. Iga lisapäev pikendab kasutusaega 24 tunni võrra ja lisab 10% baashinnast.','The base price covers 36 hours of use. Each extra day adds 24 hours and 10% of the base price.')}</div></section><dialog id="product-dialog" aria-labelledby="product-title"><div class="dialog-top"><span class="eyebrow" id="product-category"></span><button type="button" id="close-product" aria-label="${t('Sulge toode','Close product')}">×</button></div><h2 id="product-title"></h2><p id="product-description"></p><div id="product-gallery" class="product-gallery"></div><div class="rental-detail-grid"><div><div class="calendar-head"><button id="prev-month" type="button" aria-label="${t('Eelmine kuu','Previous month')}">‹</button><h3 id="month-label"></h3><button id="next-month" type="button" aria-label="${t('Järgmine kuu','Next month')}">›</button></div><div id="rental-calendar" class="calendar-grid" aria-label="${t('Saadavuse kalender','Availability calendar')}"></div><p id="calendar-status" class="small" role="status"></p><p class="calendar-legend small">${t('Valitud · Vaba · Hõivatud · Saadavus kinnitamisel','Selected · Available · Unavailable · Availability unconfirmed')}</p></div><form id="booking-form"><div class="fields"><label>${t('Rendi algus','Rental starts')}<input type="date" id="rental-date" required></label><label>${t('Kellaaeg (Eesti aeg)','Time (Estonian time)')}<select id="rental-time">${['08:00','09:00','10:00','11:00','12:00','13:00','14:00','15:00','16:00','17:00','18:00'].map(h=>`<option ${h==='10:00'?'selected':''}>${h}</option>`).join('')}</select></label><label>${t('Kogus','Quantity')}<input type="number" id="rental-quantity" min="1" max="1000" step="1" value="1" required></label><label>${t('Lisapäevi','Extra days')}<input type="number" id="extra-days" min="0" max="30" step="1" value="0" required></label></div><div id="rental-summary" aria-live="polite"></div><label>${t('Nimi','Name')}<input id="booking-name" maxlength="100" autocomplete="name" required></label><label>${t('E-post','Email')}<input id="booking-email" type="email" maxlength="200" autocomplete="email" required></label><p class="small">${t('Kasutame kontaktandmeid selle broneeringu korraldamiseks.','We use your contact details to arrange this booking.')}</p><button class="button" id="book-product" type="submit" disabled>${t('Broneeri','Book')}</button><p id="booking-status" role="status" class="small"></p></form></div></dialog>`}
async function initRentals(){
 document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{rentalFilter=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));drawProducts()});drawProducts();
 $('#close-product').onclick=()=>$('#product-dialog').close();$('#prev-month').onclick=()=>changeMonth(-1);$('#next-month').onclick=()=>changeMonth(1);
 for(const id of ['rental-date','rental-time','rental-quantity','extra-days'])$('#'+id).oninput=()=>{bookingComplete=false;if(id==='rental-date'&&$('#rental-date').value)calendarMonth=new Date($('#rental-date').value.slice(0,7)+'-01T12:00Z');calendarData=null;drawCalendar();updateRentalSummary();loadAvailability()};
 $('#booking-form').onsubmit=submitBooking;
 try{const r=await fetch('/api/products');if(!r.ok)throw Error();const data=await r.json();rentalProducts=data.products;rentalMode=data.mode;$('#catalog-status').textContent=data.products.some(p=>p.price===null||p.stock===null)?t('Tootehinnad ja kogused on täpsustamisel.','Product prices and quantities are being confirmed.'):''}catch{$('#catalog-status').textContent=t('Näidisvalik. Tootehinnad, kogused ja reaalajas saadavus vajavad kinnitamist.','Sample collection. Prices, quantities and live availability need confirmation.')}
 drawProducts();
}
function drawProducts(){const list=rentalProducts.filter(p=>p.stock!==0&&(rentalFilter==='all'||p.category===rentalFilter));$('#product-grid').innerHTML=list.length?list.map(p=>`<button class="product-card" type="button" data-product="${escapeText(p.id)}"><span class="product-square">${p.images?.[0]?`<img src="${escapeText(p.images[0])}" alt="" loading="lazy">`:""}<span class="product-category">${rentalCategories()[p.category]}</span><span class="product-title">${escapeText(p.name[lang])}</span><span class="product-open" aria-hidden="true">↗</span></span><span class="product-card-footer"><span>${p.price===null?t('Hind täpsustamisel','Price to be confirmed'):money(EheLogic.rentalPrice(p.price).total)+t(' / 36 h',' / 36 h')}</span><span>${t('Vaata kalendrit','View calendar')}</span></span></button>`).join(''):`<p class="empty-state">${t('Selle kategooria tooted lisanduvad peagi. Soovid midagi kindlat? Kirjuta karen@eheevents.ee.','Products in this category are coming soon. Looking for something specific? Email karen@eheevents.ee.')}</p>`;document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>openProduct(b.dataset.product))}
function openProduct(id){bookingComplete=false;bookingAttempt=null;selectedProduct=rentalProducts.find(p=>p.id===id);calendarData=null;calendarError=false;$('#product-title').textContent=selectedProduct.name[lang];$('#product-category').textContent=rentalCategories()[selectedProduct.category];$('#product-description').textContent=selectedProduct.description[lang];$('#product-gallery').innerHTML=(selectedProduct.images||[]).slice(0,5).map((src,i)=>`<img src="${escapeText(src)}" alt="${escapeText(selectedProduct.name[lang])} · ${i+1}">`).join('');$('#booking-form').reset();$('#rental-date').min=tallinnDate();$('#rental-date').value='';$('#rental-quantity').max=selectedProduct.stock||1000;$('#booking-status').textContent='';calendarMonth=new Date(tallinnDate()+'T12:00:00Z');calendarMonth.setUTCDate(1);$('#product-dialog').showModal();drawCalendar();updateRentalSummary();loadAvailability()}
function changeMonth(amount){calendarMonth.setUTCMonth(calendarMonth.getUTCMonth()+amount);calendarData=null;drawCalendar();loadAvailability()}
function calendarRange(){const y=calendarMonth.getUTCFullYear(),m=calendarMonth.getUTCMonth();return {from:`${y}-${String(m+1).padStart(2,'0')}-01`,to:new Date(Date.UTC(y,m+1,0)).toISOString().slice(0,10)}}
async function loadAvailability(){const request=++calendarRequest;calendarLoading=true;calendarError=false;drawCalendar();updateRentalSummary();try{if(rentalMode==='unavailable')throw Error();const range=calendarRange(),params=new URLSearchParams({from:range.from,to:range.to,time:$('#rental-time').value,quantity:$('#rental-quantity').value,extraDays:$('#extra-days').value}),r=await fetch('/api/availability/'+encodeURIComponent(selectedProduct.id)+'?'+params);if(!r.ok)throw Error();const data=await r.json();if(request!==calendarRequest)return;calendarData=data}catch{if(request!==calendarRequest)return;calendarError=true;calendarData=null}calendarLoading=false;drawCalendar();updateRentalSummary()}
function drawCalendar(){const range=calendarRange(),today=tallinnDate(),selected=$('#rental-date').value;$('#month-label').textContent=new Intl.DateTimeFormat(locale(),{month:'long',year:'numeric',timeZone:'UTC'}).format(calendarMonth);$('#prev-month').disabled=range.from<=today.slice(0,7)+'-01';const week=t('E,T,K,N,R,L,P','M,T,W,T,F,S,S').split(',');let html=week.map(x=>`<span class="weekday">${x}</span>`).join(''),offset=(new Date(range.from+'T12:00Z').getUTCDay()+6)%7;html+='<span></span>'.repeat(offset);for(let d=1;d<=+range.to.slice(-2);d++){const date=range.from.slice(0,8)+String(d).padStart(2,'0'),record=calendarData?.days?.find(x=>x.date===date),state=record?.available===true?'available':record?.available===false?'unavailable':'unknown',past=date<today,disabled=past||state==='unavailable';html+=`<button type="button" data-date="${date}" class="calendar-day ${state} ${date===selected?'selected':''}" ${disabled?'disabled':''} aria-pressed="${date===selected}" aria-label="${date} · ${past?t('Möödunud','Past'):state==='available'?t('Vaba','Available'):state==='unavailable'?t('Hõivatud','Unavailable'):t('Saadavus kinnitamisel','Availability unconfirmed')}">${d}</button>`}$('#rental-calendar').innerHTML=html;$('#calendar-status').textContent=calendarLoading?t('Kontrollime saadavust…','Checking availability…'):calendarError?t('Saadavust ei saa praegu kinnitada. Kuupäeva valik ei broneeri toodet.','Availability cannot currently be confirmed. Selecting a date does not book the item.'):calendarData?.verified?t('Kalender arvestab valitud koguse ja kogu rendiperioodiga.','The calendar accounts for your quantity and the full rental period.'):t('Saadavus kinnitatakse personaalselt.','Availability will be confirmed personally.');document.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{bookingComplete=false;$('#rental-date').value=b.dataset.date;$('#booking-status').textContent='';drawCalendar();updateRentalSummary()})}
function rentalSelection(){const date=$('#rental-date').value,extraDays=+$('#extra-days').value,quantity=+$('#rental-quantity').value;if(!date||!Number.isInteger(quantity)||quantity<1||quantity>1000||!Number.isInteger(extraDays)||extraDays<0||extraDays>30)return null;try{return {productId:selectedProduct.id,start:tallinnStart(date,$('#rental-time').value),quantity,extraDays}}catch{return null}}
function updateRentalSummary(){
 const v=rentalSelection(),quantity=+$('#rental-quantity').value,extraDays=+$('#extra-days').value,valid=Number.isInteger(quantity)&&quantity>=1&&quantity<=1000&&Number.isInteger(extraDays)&&extraDays>=0&&extraDays<=30,price=valid?EheLogic.rentalPrice(selectedProduct.price,quantity,extraDays):null;
 let text=price?'<div class="quote-row"><span>'+t('Rent','Rental')+'</span><span>'+money(price.base)+'</span></div>'+(price.extra?'<div class="quote-row"><span>'+t('Lisapäevad','Extra days')+'</span><span>'+money(price.extra)+'</span></div>':'')+'<div class="quote-row"><strong>'+t('Kokku','Total')+'</strong><strong>'+money(price.total)+'</strong></div>':'<p>'+t('Kontrollige kogust ja lisapäevade arvu.','Check the quantity and extra days.')+'</p>';
 if(v){const period=EheLogic.rentalPeriod(v.start,v.extraDays);text+='<p class="small">'+t('Kasutusaeg','Use period')+':<br>'+dateTime(period.start)+' – '+dateTime(period.customerEnd)+'</p>'}
 $('#rental-summary').innerHTML=text;const day=calendarData?.days?.find(x=>x.date===$('#rental-date').value);$('#book-product').disabled=bookingBusy||bookingComplete||!v||Date.parse(v.start)<=Date.now()||calendarLoading||(rentalMode==='direct'&&(!price||!day?.available));$('#book-product').textContent=rentalMode==='direct'?t('Broneeri','Book'):t('Küsi broneeringut','Request booking');if(!['email','direct'].includes(rentalMode))$('#book-product').disabled=true;
}
async function submitBooking(e){e.preventDefault();const v=rentalSelection();if(!v||bookingBusy)return;const name=$('#booking-name').value.trim(),email=$('#booking-email').value.trim();if(!name||!email)return;bookingBusy=true;updateRentalSummary();try{if(rentalMode==='email'){const period=EheLogic.rentalPeriod(v.start,v.extraDays),price=EheLogic.rentalPrice(selectedProduct.price,v.quantity,v.extraDays);const body=[name,email,selectedProduct.name[lang],t('Kogus: ','Quantity: ')+v.quantity,t('Algus: ','Start: ')+dateTime(v.start),t('Tagastus hiljemalt: ','Return by: ')+dateTime(period.customerEnd),t('Lisapäevi: ','Extra days: ')+v.extraDays,price?t('Kokku: ','Total: ')+money(price.total):t('Palun kinnitage hind.','Please confirm the price.')].join('\n');location.href='mailto:karen@eheevents.ee?subject='+encodeURIComponent(t('Rendi broneerimistaotlus','Rental booking request'))+'&body='+encodeURIComponent(body);$('#booking-status').textContent=t('Saatke taotlus oma e-posti rakenduses. Broneering ja saadavus kinnitatakse vastusega; kuupäev pole veel reserveeritud.','Send the request from your email app. Booking and availability will be confirmed in the reply; the date is not reserved yet.');return}const r=await fetch('/api/bookings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...v,name,email,requestKey:bookingRequestKey({...v,name,email})})}),data=await r.json();if(!r.ok)throw Error(data.code||'unavailable');bookingComplete=true;$('#booking-status').textContent=t('Broneering kinnitatud. Viide: ','Booking confirmed. Reference: ')+data.reference+'. '+t('Tagastus hiljemalt: ','Return by: ')+dateTime(data.customerEnd)+'. '+t('Salvestage see viide.','Please save this reference.');await loadAvailability()}catch(error){$('#booking-status').textContent=error.message==='conflict'?t('See periood ei ole enam vaba. Valige teine aeg.','This period is no longer available. Please choose another time.'):t('Broneerimine ei õnnestunud. Palun proovige uuesti või kirjutage karen@eheevents.ee.','Booking failed. Please try again or email karen@eheevents.ee.');await loadAvailability()}finally{bookingBusy=false;updateRentalSummary()}}

function bookingRequestKey(value){const signature=JSON.stringify(value);if(bookingAttempt?.signature!==signature)bookingAttempt={signature,key:crypto.randomUUID()};return bookingAttempt.key}
